/* Source adapters only. No Quran text or translation is generated by this module. */
window.ZadQuranSources = (() => {
  'use strict';
  const names = {
    en: 'english',
    fr: 'french',
    id: 'indonesian',
    tr: 'turkish',
    ur: 'urdu',
    es: 'spanish'
  };
  const fallback = {
    en: 'en.sahih',
    fr: 'fr.hamidullah',
    id: 'id.indonesian',
    tr: 'tr.diyanet',
    ur: 'ur.jalandhry',
    es: 'es.cortes'
  };
  const cache = new Map();
  let resourcePromise = null,
    resourceFailedAt = 0;
  async function resources() {
    if (resourceFailedAt && Date.now() - resourceFailedAt < 60000) throw new Error('resource unavailable');
    if (!resourcePromise) resourcePromise = Zad.fetch('https://api.quran.com/api/v4/resources/translations?language=en').then(async r => {
      if (!r.ok) throw new Error('resource unavailable');
      const j = await r.json();
      if (!Array.isArray(j.translations)) throw new Error('invalid resource list');
      return j.translations;
    }).catch(error => {
      resourcePromise = null;
      resourceFailedAt = Date.now();
      throw error;
    });
    return resourcePromise;
  }

  function selectResource(list, code) {
    const rows = list.filter(r => String(r.language_name || '').toLowerCase() === names[code]);
    const preferred = {
      en: 131,
      id: 33
    } [code];
    return rows.find(r => Number(r.id || r.resource_id) === preferred) || rows[0] || null;
  }
  async function primary(chapter, code) {
    const resource = selectResource(await resources(), code);
    if (!resource) throw new Error('language unavailable');
    const id = Number(resource.id || resource.resource_id);
    if (!Number.isInteger(id) || id < 1) throw new Error('invalid resource');
    const r = await Zad.fetch(`https://api.quran.com/api/v4/quran/translations/${id}?chapter_number=${chapter}&fields=verse_number,verse_key,chapter_id`);
    if (!r.ok) throw new Error('translation unavailable');
    const j = await r.json(),
      map = new Map();
    for (const row of j.translations || [])
      if (new RegExp('^' + chapter + ':\\d+$').test(String(row.verse_key)) && typeof row.text === 'string') map.set(row.verse_key, Zad.plainHTML(row.text));
    if (!map.size) throw new Error('empty translation');
    map.source = 'Quran.com · ' + String(resource.name || resource.author_name || id);
    return map;
  }
  async function secondary(chapter, code) {
    const edition = fallback[code];
    if (!edition) throw new Error('language unavailable');
    const r = await Zad.fetch(`https://api.alquran.cloud/v1/surah/${chapter}/${edition}`);
    if (!r.ok) throw new Error('translation unavailable');
    const j = await r.json(),
      data = j.data;
    if (!data || Number(data.number) !== chapter || data.edition?.language !== code || data.edition?.identifier !== edition || !Array.isArray(data.ayahs)) throw new Error('invalid translation');
    const map = new Map(data.ayahs.filter(a => Number.isInteger(Number(a.numberInSurah)) && typeof a.text === 'string').map(a => [chapter + ':' + a.numberInSurah, a.text]));
    if (!map.size) throw new Error('empty translation');
    const name = data.edition.englishName && data.edition.englishName !== 'Unknown' ? data.edition.englishName : data.edition.name;
    map.source = 'Al Quran Cloud · ' + String(name || edition);
    map.fallback = true;
    return map;
  }
  async function translations(chapter, code) {
    chapter = Number(chapter);
    if (!Number.isInteger(chapter) || chapter < 1 || chapter > 114 || !fallback[code]) return new Map();
    const key = code + ':' + chapter;
    if (cache.has(key)) return cache.get(key);
    const task = primary(chapter, code).catch(() => secondary(chapter, code));
    cache.set(key, task);
    try {
      return await task;
    } catch (_) {
      cache.delete(key);
      return new Map();
    }
  }
  return {
    translations,
    selectResource
  };
})();

